def norm(s):
    s=unicodedata.normalize('NFKD',s).casefold().replace('α','alpha').replace('β','beta').replace('γ','gamma')
    return re.sub(r'[^a-z0-9]+',' ',s).strip()
def dump(path,obj): path.write_text(json.dumps(obj,indent=2,ensure_ascii=False)+'\n')
