b('B035','Surface binding versus internalization assay','Methods','Pair surface-bound probe and intracellular probe panels using the same receptor/ligand group and a time annotation.','transmembrane protein;fluorophore-conjugated antibody;early endosome','Verify controls that distinguish internalization from surface signal; fluorescence location alone may be insufficient.','roadmap:103')
b('B036','Chromatographic separation and fraction identity','Methods','Link a sample mixture to a column, editable elution trace and individual fraction tubes with consistent component colors.','size-exclusion chromatography column;generic globular protein;fraction collector;microcentrifuge tube','Verify separation principle and calibration; elution position is not automatically molecular identity.','size-exclusion chromatography column')

# Remove two redundant recipes: their state comparisons already belong to primitives.
R=[r for r in R if r['id'] not in {'C015','C024'}]

BASE_FILES=['docs/ai-bioart-asset-inventory.md','docs/ai-bioart-asset-inventory-additions.md','docs/assembled-assets-roadmap.md','experiments/ai-assets/nih-bioart-collection/inventory-progress.json']
snapshots=[]
for rel in BASE_FILES:
    expected=subprocess.check_output(['git','show',f'{BASE}:{rel}'],cwd=ROOT)
    actual=(ROOT/rel).read_bytes()
    assert actual==expected, f'Protected baseline changed: {rel}'
    snapshots.append(dict(path=rel,sha256=hashlib.sha256(actual).hexdigest()))
rows=[]
for rel in BASE_FILES[:2]:
    for lineno,line in enumerate((ROOT/rel).read_text().splitlines(),1):
        match=re.match(r'^- \[[ xX]\] (.+)$',line)
        if match: rows.append(dict(name=match[1],path=rel,line=lineno))
assert len(rows)==770
names={r['name'] for r in rows}
assert len(names)==768
progress=json.loads((ROOT/BASE_FILES[3]).read_text())
entries={e['name']:e for e in progress['entries']}
assert names==set(entries), 'Progress and inventory differ'
base_assets={}
collection=ROOT/'experiments/ai-assets/nih-bioart-collection'
for name in sorted(names,key=norm):
    e=entries[name]; item=progress['assets'].get(e['id'],{})
    files={}
    for fmt in ['png','svg']:
        rel=item.get(fmt)
        if rel:
            path=collection/rel
            exists=path.is_file()
            expected=item.get(fmt+'_sha256')
            matches=exists and bool(expected) and hashlib.sha256(path.read_bytes()).hexdigest()==expected
            files[fmt]=dict(path=str(path.relative_to(ROOT)),exists_at_snapshot=exists,sha256_matches_record=matches)
    base_assets[name]=dict(id=e['id'],name=name,category=e['category'],status_at_snapshot=item.get('status','not_recorded'),files=files,inventory_rows=[r for r in rows if r['name']==name])
source_map={s['source_id']:s for s in S}
all_records=R+B
record_map={r['id']:r for r in all_records}
assert len(record_map)==len(all_records)
assert len({norm(r['name']) for r in all_records})==len(all_records)
base_norm={norm(n):n for n in names}
roadmap=(ROOT/BASE_FILES[2]).read_text()
roadmap_items={int(m[1]):m[2] for m in re.finditer(r'^(\d+)\. (.+)$',roadmap,re.M)}
assert len(roadmap_items)==136, len(roadmap_items)
for r in all_records:
    assert norm(r['name']) not in base_norm, f'Exact-name duplicate: {r["name"]}'
    r['components']=[]
    for name in r['component_names']:
        if ':' in name:
            prefix,id=name.split(':',1)
            assert prefix in ['new','preset','composite'] and id in record_map, name
            target=record_map[id]
            expected={'new':'new_primitive','preset':'reuse_preset','composite':'composite'}[prefix]
            assert target['kind']==expected,(name,target['kind'])
            r['components'].append(dict(reference=id,name=target['name'],origin='this_plan',availability='planned_not_generated'))
        else:
            assert name in base_assets, f'{r["id"]}: unknown component {name}'
            item=base_assets[name]
            r['components'].append(dict(reference=item['id'],name=name,origin='baseline_768',status_at_snapshot=item['status_at_snapshot'],files=item['files']))
    for number in re.findall(r'roadmap:(\d+)',r.get('related_baseline','')):
        assert int(number) in roadmap_items,number
    if r['kind']!='brainstorm':
        assert r['source_ids'] and all(x in source_map for x in r['source_ids'])
        assert all(r.get(field) for field in ['scientific_description','design_instructions','scientific_caveat','states','related_baseline'] if field!='related_baseline')
        r['evidence']=[dict(source_id=x,url=source_map[x]['url'],location=source_map[x]['evidence_location']) for x in r['source_ids']]
        r['deduplication_decision']=r['related_baseline'] or 'No matching named primitive or numbered roadmap recipe found in manual topic comparison. This is a new recipe, not a new primitive.'
        if r['kind']=='composite':
            r['assembly_contract']='Instantiate linked component assets; group them with editable transforms, labels and typed connectors. Resolve pending primitives first. Do not generate or flatten the complete scene into a new SVG.'

def visit(id,stack=()):
    assert id not in stack, f'Component dependency cycle: {stack+(id,)}'
    for dep in record_map[id]['components']:
        if dep['origin']=='this_plan': visit(dep['reference'],stack+(id,))
for id in record_map: visit(id)
counts=dict(collection_rows=len(rows),baseline_unique_names=len(names),existing_roadmap_concepts=len(roadmap_items),verified_specs=len(R),new_primitive_candidates=sum(r['kind']=='new_primitive' for r in R),reuse_presets=sum(r['kind']=='reuse_preset' for r in R),composite_recipes=sum(r['kind']=='composite' for r in R),new_composite_topics=sum(r['kind']=='composite' and r['novelty']=='new' for r in R),expanded_existing_composites=sum(r['kind']=='composite' and r['novelty']!='new' for r in R),brainstorm_candidates=len(B),sources=len(S))
