dump(OUT/'research/sources.json',S)

def links(r): return '; '.join(f'[{key}]({source_map[key]["url"]}) ({source_map[key]["evidence_location"]})' for key in r['source_ids'])
def component_text(r):
    return '; '.join(f'`{d["reference"]}` ({d["name"]}; '+(d['status_at_snapshot']+' at baseline' if d['origin']=='baseline_768' else 'planned in this catalog')+')' for d in r['components'])
def render(group,title,intro):
    text=f'# {title}\n\n{intro}\n\n[Catalog guide](README.md) · [Assembly rules](ASSEMBLY-INSTRUCTIONS.md)\n\n'
    for r in group:
        text+=f'## {r["id"]} — {r["name"]}\n\n'
        text+=f'**Category:** {r["category"]}. **Disposition:** {r["novelty"]}.\n\n'
        if r['kind']=='brainstorm':
            text+=f'**Proposed scene:** {r["design_proposal"]}\n\n**Required verification:** {r["required_verification"]}\n\n**Existing coverage:** {r["related_baseline"]}. Expand that concept; do not add a duplicate primitive.\n\n'
        else:
            text+=f'**Verified scientific scope:** {r["scientific_description"]}\n\n**Proposed construction:** {r["design_instructions"]}\n\n**States:** {"; ".join(r["states"])}.\n\n**Limits:** {r["scientific_caveat"]}\n\n**Deduplication:** {r["deduplication_decision"]}\n\n**Evidence:** {links(r)}\n\n'
        text+=f'**Reusable dependencies:** {component_text(r)}.\n\n'
    return text.rstrip()+'\n'
(OUT/'NEW-ASSETS.md').write_text(render([r for r in R if r['kind']=='new_primitive'],'New building-block candidates','12 distinct morphology or topology candidates after comparison with the 768-name baseline. These are planning requests, not permission to generate artwork. First try existing editable geometry; a candidate that can be expressed as a preset should remain a preset.'))
(OUT/'REUSE-PRESETS.md').write_text(render([r for r in R if r['kind']=='reuse_preset'],'Reuse and identity presets','18 configurations of existing artwork. None counts as a new primitive. Labels, state overlays and placement rules carry the specialization.'))
(OUT/'COMPOSITES.md').write_text(render([r for r in R if r['kind']=='composite'],'Composite recipes','40 source-checked schematic recipes. Disposition distinguishes new topics from expansions of existing inventory/roadmap concepts. Every recipe assembles library instances; the recipe itself is not a request for a new full-scene SVG.'))
(OUT/'BRAINSTORM.md').write_text(render(B,'Further asset and recipe ideas','36 independently brainstormed specializations. These have not been source-verified and are not ready for scientific implementation. Each lists the exact check still required and existing library coverage. Do not count them as 36 new primitive assets.'))

